# Generates real page components from compact specs using the app's established
# patterns (list / form / detail). Each emitted file is a normal standalone
# component — no runtime magic. Re-run safe: overwrites generated files only
# when the spec's `overwrite` marker allows (all files carry a "generated"
# note; hand-written files must NOT include that marker).
import os

BASE = os.path.join(os.path.dirname(__file__), '..', 'src', 'app', 'features')

GEN_NOTE = '// Generated by scripts/gen-pages.py from the page specs — edit the spec or this file.\n'

# ── shared template pieces ──────────────────────────────────────────

COMMON_IMPORTS_LIST = """import { ChangeDetectionStrategy, Component, computed, inject, resource, signal } from '@angular/core';
import { RouterLink } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { TranslatePipe } from '@ngx-translate/core';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { ButtonModule } from 'primeng/button';
import { InputTextModule } from 'primeng/inputtext';
import { SelectModule } from 'primeng/select';
import { ToastService } from '@core/errors/toast.service';
import { PageHeaderComponent } from '@shared/ui/page-header/page-header.component';
import { StatTileComponent } from '@shared/ui/stat-tile/stat-tile.component';
import { DataTableComponent, TableBodyDirective } from '@shared/ui/data-table/data-table.component';
import { EmptyStateComponent } from '@shared/ui/empty-state/empty-state.component';
import { MoneyPipe } from '@shared/pipes/money.pipe';
import { DatetimePipe } from '@shared/pipes/datetime.pipe';
import { EnumLabelPipe } from '@shared/pipes/enum-label.pipe';
import { StatusStampComponent } from '@shared/ui/status-stamp/status-stamp.component';
import { ListResponse } from '@shared/models/api.models';"""


def list_page(spec):
    endpoint = spec['endpoint']
    row = spec['row']
    cols = spec['columns']
    summary = spec.get('summary', [])
    filters = spec.get('filters', [])
    actions = spec.get('actions', '')

    cols_ts = ',\n'.join(
        f"    {{ field: '{c[0]}', header: '{c[1]}'{', numeric: True' if c[2] == 'num' else ''}{', sortable: True' if len(c) > 3 and c[3] else ''} }}"
        .replace('True', 'true')
        for c in cols
    )

    def cell(c):
        field, _, kind = c[0], c[1], c[2]
        if kind == 'num':
            return f'<span class="u-bidi">{{{{ row.{field} | money }}}}</span>'
        if kind == 'money':
            return f'<span class="u-bidi">{{{{ row.{field} | money }}}}</span>'
        if kind == 'date':
            return f'<span class="u-bidi">{{{{ row.{field} | datetime }}}}</span>'
        if kind == 'enum':
            return f'{{{{ row.{field} | enumLabel: \'{c[3]}\' }}}}' if len(c) > 3 else f'{{{{ row.{field} }}}}'
        if kind == 'stamp':
            return f'<app-status-stamp [status]="row.{field}" namespace="{c[3]}" />' if len(c) > 3 else f'{{{{ row.{field} }}}}'
        return f'{{{{ row.{field} ?? \'—\' }}}}'

    desktop_cells = '\n'.join(
        f'            <td{" class=\"ledger-table__cell-num\"" if c[2] in ("num", "money") else ""}>{cell(c)}</td>' for c in cols
    )
    stacked_cells = '\n'.join(
        f'''            <div class="ledger-table__stacked-item">
              <span class="ledger-table__stacked-label">{{{{ '{c[1]}' | translate }}}}</span>
              {cell(c)}
            </div>''' for c in cols
    )

    filter_controls = '\n'.join(filters)
    empty_title = spec.get('empty_title') or 'common.no_data'
    empty_text = spec.get('empty_text') or 'common.no_data'
    stat_tiles = ''
    for s in summary:
        money_attr = ' [money]="true"' if s[2] == 'money' else ''
        stat_tiles += f"        <app-stat-tile [label]=\"'{s[0]}'\" [value]=\"summaryValue('{s[1]}')\"{money_attr} />\n"

    return f"""{GEN_NOTE}
{COMMON_IMPORTS_LIST}

interface Row {{
{chr(10).join(f'  {f}: {t};' for f, t in row.items())}
}}

{spec['doc']}
@Component({{
  selector: '{spec['selector']}',
  standalone: true,
  imports: [
    TranslatePipe, RouterLink, FormsModule, ButtonModule, InputTextModule, SelectModule,
    PageHeaderComponent, StatTileComponent, DataTableComponent, TableBodyDirective,
    EmptyStateComponent, MoneyPipe, DatetimePipe, EnumLabelPipe, StatusStampComponent,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <app-page-header [title]="'{spec['title']}' | translate">
      <div actions class="u-flex u-gap-2">
{actions}
      </div>
    </app-page-header>

    @if (data.isLoading()) {{
      <div class="kpi-grid">@for (s of [1, 2, 3, 4]; track s) {{<div class="skeleton skeleton--tile"></div>}}</div>
    }} @else if (data.value(); as page) {{
{stat_tiles}

      <app-data-table
        [tableKey]="tableKey"
        [columns]="columns"
        [rows]="page.data"
        [total]="page.meta.total"
        [perPage]="params().per_page"
        [loading]="data.isLoading()"
        (pageChange)="onPage($event)"
      >
        <div toolbar class="u-flex u-gap-2 u-flex-wrap">
          <input pInputText type="search" size="small" [placeholder]="'common.search' | translate"
                 [ngModel]="params().q" (ngModelChange)="onSearch($event)" />
{filter_controls}
        </div>
        <ng-template appTableBody let-row>
          <tr class="ledger-table__row">
{desktop_cells}
          </tr>
          <tr class="ledger-table__stacked">
{stacked_cells}
          </tr>
        </ng-template>
        <div empty>
          <app-empty-state [title]="'{empty_title}' | translate" [text]="'{empty_text}' | translate" />
        </div>
      </app-data-table>
    }}
  `,
}})
export class {spec['class']} {{
  private http = inject(HttpClient);
  private toast = inject(ToastService);

  readonly tableKey = 'table';

  readonly columns = [
{cols_ts}
  ];

  params = signal({{ page: 1, per_page: 25, q: '', status: 'all' }});

  data = resource<ListResponse<Row>, {{ page: number; per_page: number; q: string; status: string }}>({{
    params: () => this.params(),
    loader: ({{ params }}) =>
      firstValueFrom(this.http.get<ListResponse<Row>>('{endpoint}', {{ params: cleanParams(params) }})),
  }});

  summaryValue(key: string): string {{
    const value = this.data.value()?.meta.summary?.[key];
    return value === undefined || value === null ? '0' : String(value);
  }}

  setParam(key: string, value: string): void {{
    this.params.update((p) => ({{ ...p, [key]: value, page: 1 }}));
    this.data.reload();
  }}

  onSearch(term: string): void {{ this.setParam('q', term); }}

  onPage(event: {{ page: number; per_page: number; sort?: string }}): void {{
    const current = this.params();
    const sort = event.sort ?? '';
    if (current.page === event.page && current.per_page === event.per_page) {{
      return;
    }}
    this.params.update((p) => ({{ ...p, page: event.page, per_page: event.per_page }}));
    this.data.reload();
  }}
}}

function cleanParams(params: Record<string, unknown>): Record<string, string> {{
  const result: Record<string, string> = {{}};
  for (const [key, value] of Object.entries(params)) {{
    if (value !== null && value !== undefined && value !== '' && value !== 'all') {{
      result[key] = String(value);
    }}
  }}
  return result;
}}
"""


def detail_page(spec):
    fields = spec['fields']
    kv_items = '\n'.join(
        f'      {{ label: \'{label}\', value: String(item.{field} ?? \'—\') }},' for field, label in fields
    )
    return f"""{GEN_NOTE}
import {{ ChangeDetectionStrategy, Component, inject, input, resource }} from '@angular/core';
import {{ RouterLink }} from '@angular/router';
import {{ TranslatePipe }} from '@ngx-translate/core';
import {{ HttpClient }} from '@angular/common/http';
import {{ firstValueFrom }} from 'rxjs';
import {{ ButtonModule }} from 'primeng/button';
import {{ ToastService }} from '@core/errors/toast.service';
import {{ PageHeaderComponent }} from '@shared/ui/page-header/page-header.component';
import {{ KeyValueListComponent }} from '@shared/ui/key-value-list/key-value-list.component';
import {{ PrintSheetComponent }} from '@shared/ui/print-sheet/print-sheet.component';
import {{ StatusStampComponent }} from '@shared/ui/status-stamp/status-stamp.component';
import {{ ItemResponse }} from '@shared/models/api.models';

{spec['doc']}
@Component({{
  selector: '{spec['selector']}',
  standalone: true,
  imports: [TranslatePipe, RouterLink, ButtonModule, PageHeaderComponent, KeyValueListComponent, PrintSheetComponent, StatusStampComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (data.value(); as item) {{
      <app-print-sheet [title]="'{spec['title']}' | translate">
        <app-page-header [title]="itemTitle(item)" [subtitle]="'{spec['subtitle']}' | translate">
          <div actions class="u-flex u-gap-2">
            <p-button [label]="'common.print' | translate" size="small" [outlined]="true" (click)="printPage()" />
            <p-button [label]="'common.back_to_list' | translate" size="small" [text]="true" routerLink="{spec['back_link']}" />
          </div>
        </app-page-header>
        <div class="u-mb-4">
          <app-status-stamp [status]="item.{spec['status_field']}" namespace="{spec['status_ns']}" [large]="true" />
        </div>
        <app-key-value-list [items]="keyValues(item)" />
        <div class="u-mt-4"><ng-content /></div>
      </app-print-sheet>
    }} @else {{
      <div class="skeleton skeleton--title u-mb-4"></div>
      <div class="skeleton skeleton--tile"></div>
    }}
  `,
}})
export class {spec['class']} {{
  private http = inject(HttpClient);

  id = input.required<number>();

  data = resource<{spec['item_type']}, {{ id: number }}>({{
    params: () => ({{ id: this.id() }}),
    loader: ({{ params }}) =>
      firstValueFrom(this.http.get<ItemResponse<{spec['item_type']}>>('{spec['endpoint']}' + '/' + params.id)).then((res) => res.data),
  }});

  itemTitle(item: {spec['item_type']}): string {{
    return String(item.{spec['title_field']} ?? '#{spec.get('title_prefix', '')}');
  }}

  keyValues(item: {spec['item_type']}): {{ label: string; value: string }}[] {{
    return [
{kv_items}
    ];
  }}

  printPage(): void {{ window.print(); }}
}}
"""


def write(feature, page_dir, filename, content):
    path = os.path.join(BASE, feature, 'pages', page_dir)
    os.makedirs(path, exist_ok=True)
    with open(os.path.join(path, filename), 'w', encoding='utf-8', newline='\n') as f:
        f.write(content)
    print('wrote', os.path.join(feature, 'pages', page_dir, filename))
